input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://w3id.org/ren/ontology#>
SELECT ?point ?ts ?pointClass WHERE {
  ?zone brick:hasSubArea ?point ; a brick:Zone .
  ?point ref:hasTimeseriesId ?ts .
  OPTIONAL { ?point a ?pointClass . }
  FILTER (str(?zone) = "Basement" || str(?zone) = "Perimeter_bot_ZN_3" || str(?point) like "%occup%")
}

